import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import test from "node:test";
import type { ToolDefinition } from "@crewon/tool-broker";

import {
  compileAgentVersion,
  createAgentVersionAsset,
  parseAgentVersionAsset,
  type AgentVersionSource,
} from "./agent-version.ts";

// Captured from the previous compiler, not generated by the implementation under test.
const legacyAsset = JSON.parse(
  readFileSync(
    new URL("./fixtures/legacy-agent-version.json", import.meta.url),
    "utf8",
  ),
);
const digester = {
  sha256: (value: string) =>
    `sha256:${createHash("sha256").update(value).digest("hex")}`,
};

test("equal version digests produce identical runtime JSON across object order and durable reload", () => {
  const source = legacySource();
  const reversed = reverseObjectKeys(source) as AgentVersionSource;
  assert.notEqual(JSON.stringify(source.tools), JSON.stringify(reversed.tools));
  const first = compileAgentVersion(source, digester);
  const second = compileAgentVersion(reversed, digester);
  const restored = parseAgentVersionAsset(asset(second), digester);
  assert.equal(first.contentDigest, second.contentDigest);
  assert.equal(JSON.stringify(second), JSON.stringify(first));
  assert.equal(JSON.stringify(restored), JSON.stringify(first));
});

test("canonical materialization preserves arrays and text and detaches mutable source objects", () => {
  const source = reverseObjectKeys(legacySource()) as AgentVersionSource;
  const before = structuredClone(source);
  const version = compileAgentVersion(source, digester);
  assert.deepEqual(source, before);
  assert.deepEqual(version.tools, source.tools);
  assert.equal(version.instructions, source.instructions);
  assert.deepEqual(
    version.tools.map((tool) => tool.name),
    ["z_read", "a_patch"],
  );
  const tool = version.tools[0];
  assert.equal(tool.kind, "function");
  if (tool.kind !== "function") throw new Error("missing function");
  assert.ok(Object.isFrozen(tool.inputSchema));
  assert.ok(Object.isFrozen(tool.inputSchema.properties));
  assert.ok(Object.isFrozen(tool.inputSchema.required));
  const sourceTool = source.tools[0];
  if (sourceTool.kind !== "function") throw new Error("missing function");
  (sourceTool.inputSchema as Record<string, unknown>).required = ["changed"];
  assert.deepEqual(tool.inputSchema.required, ["path", "mode"]);
  assert.notEqual(
    compileAgentVersion(
      { ...before, tools: [...before.tools].reverse() },
      digester,
    ).contentDigest,
    version.contentDigest,
  );
});

test("previously persisted normal assets retain their digest and exact serialized definition", () => {
  assert.equal(
    legacyAsset.contentDigest,
    "sha256:10ba6e7cd0a807ad1c02171d753ad33f4bb337b9b9159a2eb9f4c6e5464d63dc",
  );
  const restored = parseAgentVersionAsset(legacyAsset, digester);
  assert.deepEqual(asset(restored), legacyAsset);
  assert.equal(
    JSON.stringify(restored.tools),
    JSON.stringify(JSON.parse(legacyAsset.definitionJson).tools),
  );
});

test("JSON property names including __proto__ remain own properties and participate in the digest", () => {
  const inputSchema = JSON.parse(
    '{"type":"object","properties":{"__proto__":{"type":"string"},"constructor":{"type":"number"},"prototype":{"type":"boolean"}},"required":["__proto__","constructor","prototype"]}',
  );
  const source = withSchema(inputSchema);
  const version = compileAgentVersion(source, digester);
  const restored = parseAgentVersionAsset(asset(version), digester);
  for (const current of [version, restored]) {
    const tool = current.tools[0];
    if (tool.kind !== "function") throw new Error("missing function");
    assert.deepEqual(tool.inputSchema, inputSchema);
    const properties = tool.inputSchema.properties as Record<string, unknown>;
    assert.ok(Object.hasOwn(properties, "__proto__"));
    assert.equal(Object.getPrototypeOf(properties), Object.prototype);
    assert.ok(Object.isFrozen(properties["__proto__"]));
  }
  const omitted = structuredClone(inputSchema);
  delete omitted.properties["__proto__"];
  const changed = compileAgentVersion(withSchema(omitted), digester);
  assert.notEqual(version.contentDigest, changed.contentDigest);
  assert.throws(
    () => compileAgentVersion(source, digester, changed.contentDigest),
    { code: "agent_version_digest_mismatch" },
  );
});

function legacySource(): AgentVersionSource {
  const { contentDigest: _digest, ...definition } = JSON.parse(
    legacyAsset.definitionJson,
  );
  return { ...definition, schemaVersion: "crewon.agent-version-source.v0" };
}

function withSchema(
  inputSchema: Extract<ToolDefinition, { kind: "function" }>["inputSchema"],
): AgentVersionSource {
  const source = legacySource();
  const tool = source.tools[0];
  if (tool.kind !== "function") throw new Error("missing function");
  return { ...source, tools: [{ ...tool, inputSchema }] };
}

function asset(version: ReturnType<typeof compileAgentVersion>) {
  return createAgentVersionAsset({
    tenantId: legacyAsset.tenantId,
    version,
    createdAt: legacyAsset.createdAt,
  });
}

function reverseObjectKeys(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(reverseObjectKeys);
  if (value === null || typeof value !== "object") return value;
  return Object.fromEntries(
    Object.entries(value)
      .reverse()
      .map(([key, item]) => [key, reverseObjectKeys(item)]),
  );
}
